questionvariables.text:
/* Design: [er, s, a, c, b, wp]: er 1 the "and" line adds, er 2 the one-die "or" line multiplies, er 3 the overlapping "or" line adds; wp = position (2 or 3) of the wrong line. Shown values differ from the correct ones on every entry. Source: original. */
L: [[1,8,5,1,3,2],[2,4,4,5,2,3],[3,4,3,1,2,3],[1,5,5,4,5,3],[2,5,6,2,3,3],[3,8,2,1,5,2],[1,8,5,4,3,3],[2,4,5,3,2,3],[3,8,2,6,8,2],[2,4,5,6,2,2]];
ix: 1+rand(10);
er: L[ix][1]; s: L[ix][2]; a: L[ix][3]; c: L[ix][4]; b: L[ix][5]; wp: L[ix][6];
/* line kinds: 1 "and", 2 one-die "or", 3 overlapping "or"; ord = kind shown at positions 1..3 */
oth: delete(er,[1,2,3]);
ord: if wp=2 then [oth[1],er,oth[2]] else [oth[1],oth[2],er];
pos(kd) := first(sublist([1,2,3], lambda([u], ord[u]=kd)));
mel: pos(2);
ta3: if er=1 then 1/(6*s) elseif er=2 then 1/3 else (s+5)/(6*s);
bv: if er=2 then 1/36 else 1/6+1/s;
tl3: min(1/200,ta3/20);
lk: if wp=2 then "l2" else "l3";
lo: if wp=2 then "l3" else "l2";
rk: if er=1 then "r1" elseif er=2 then "r2" else "r3";
rw: if er=1 then "r2" else "r1";
opts1: [["l1",false,"Line 1"],["l2",is(wp=2),"Line 2"],["l3",is(wp=3),"Line 3"]];
opts2: [["r0",false,"Probabilities should never be added."],["r1",is(er=1),"Both events must happen and they are independent, so he should multiply, not add."],["r2",is(er=2),"The die cannot show both numbers at once, so he should add, not multiply."],["r3",is(er=3),"The two events can happen together, so adding counts the outcome where both happen twice."]];
